import { revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

export default async function Page() {
  const products = await getAllProducts();

  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <header style={{ marginBottom: '2rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h1 style={{ margin: 0 }}>Product Catalog</h1>
        <form action={syncCatalog}>
          <button 
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              background: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </header>

      <div style={{ display: 'grid', gap: '1rem', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))' }}>
        {products.map((product: any) => (
          <div key={product.id} style={{ border: '1px solid #eaeaea', padding: '1rem', borderRadius: '4px' }}>
            <h2 style={{ margin: '0 0 0.5rem 0', fontSize: '1.1rem' }}>{product.name}</h2>
            <p style={{ margin: 0, color: '#666' }}>${product.price}</p>
          </div>
        ))}
      </div>
    </main>
  );
}

